create policy visual_approval_read on app.approvals for select to ts_runtime using(app.scope_ok(tenant_id,workspace_id) and owner_id=current_setting('ts.user',true) and data->>'kind'='VISUAL_PROOF');
create policy visual_approval_insert on app.approvals for insert to ts_runtime with check(app.scope_ok(tenant_id,workspace_id) and owner_id=current_setting('ts.user',true) and data->>'kind'='VISUAL_PROOF');
